fixture.setup:
mkdir -p fixture/src && cd fixture && cat > src/app.js << 'EOF'
express = require('express');
const app = express();

app.use(express.json());

// BUG: express 4.19 changed path matching - need exact match or trailing slash
app.get('/api/users', (req, res) => {
  res.json([{ id: 1, name: 'Alice' }]);
});

module.exports = app;
EOF
cat > src/app.test.js << 'EOF'
const request = require('supertest');
const app = require('./app');

test('GET /api/users returns users', async () => {
  const res = await request(app).get('/api/users');
  expect(res.status).toBe(200);
  expect(res.body).toHaveLength(1);
});
EOF
cat > package.json << 'EOF'
{
  "name": "upgrade-regression-fixture",
  "version": "1.0.0",
  "scripts": { "test": "node --test src/app.test.js" },
  "dependencies": { "express": "4.18.0", "supertest": "^6.3.0" },
  "type": "module"
}
EOF
cd fixture && npm install && npm install express@4.19.0
